// 중복 제거: source_url 해시 기준
const seen = new Set();
return items.filter(it => {
  const url = it.json.link;
  if (!url || seen.has(url)) return false;
  seen.add(url);
  return true;
}).slice(0, 20);

// 가타카나 -> 한국어 발음 매핑 (간이 매핑 테이블 예시)
const kanaToKorean = {
  'ア':'아','イ':'이','ウ':'우','エ':'에','オ':'오',
  'カ':'카','キ':'키','ク':'쿠','ケ':'케','コ':'코',
  'サ':'사','シ':'시','ス':'스','セ':'세','ソ':'소',
  'タ':'타','チ':'치','ツ':'츠','テ':'테','ト':'토',
  'ナ':'나','ニ':'니','ヌ':'누','ネ':'네','ノ':'노',
  'ハ':'하','ヒ':'히','フ':'후','ヘ':'헤','ホ':'호',
  'マ':'마','ミ':'미','ム':'무','メ':'메','モ':'모',
  'ヤ':'야','ユ':'유','ヨ':'요',
  'ラ':'라','リ':'리','ル':'루','レ':'레','ロ':'로',
  'ワ':'와','ヲ':'오','ン':'ㄴ',
  'ガ':'가','ギ':'기','グ':'구','ゲ':'게','ゴ':'고',
  'ザ':'자','ジ':'지','ズ':'즈','ゼ':'제','ゾ':'조',
  'ダ':'다','ヂ':'지','ヅ':'즈','デ':'데','ド':'도',
  'バ':'바','ビ':'비','ブ':'부','ベ':'베','ボ':'보',
  'パ':'파','ピ':'피','プ':'푸','ペ':'페','ポ':'포',
  'ー':''
};
function toKorean(kana) {
  if (!kana) return '';
  return [...kana].map(c => kanaToKorean[c] || c).join('');
}
const tokens = ($json.tokens || []).map((t, idx, arr) => ({
  surface: t.surface,
  reading: toKorean(t.reading_kana || ''),
  pos: t.pos,
  startIdx: arr.slice(0, idx).reduce((s, x) => s + (x.surface?.length || 0), 0),
  endIdx: arr.slice(0, idx + 1).reduce((s, x) => s + (x.surface?.length || 0), 0)
}));
return [{ json: { ...$json, tokens } }];

