// 토큰별 의미 병합
const llm = JSON.parse($json.choices[0].message.content);
const tokens = ($json.tokens || []).map((t, i) => ({
  ...t,
  meaning: (llm.token_meanings || [])[i] || ''
}));
return [{
  json: {
    source: 'NHK',
    source_url: $json.link,
    title_jp: $json.title,
    title_ko: llm.title_ko,
    body_jp: $json.contentSnippet,
    body_ko: llm.body_ko,
    tokens,
    published_at: $json.pubDate
  }
}];
